#include <set>
#include <iostream>

int main() {
    std::set<int> s = {10, 20, 40, 50};

    // Case 1: Value exists (returns iterator to 40)
    auto it1 = s.lower_bound(40);
    std::cout << *it1 << " (Found 40)\n";

    // Case 2: Value does not exist (returns iterator to 20, the first element >= 15)
    auto it2 = s.lower_bound(15);
    std::cout << *it2 << " (Insertion point for 15)\n";

    // Case 3: Value is larger than all elements (returns end())
    auto it3 = s.lower_bound(100);
    if (it3 == s.end()) {
        std::cout << "Returns end() for 100.\n";
    }
}
